const { Worker } = await import('node:worker_threads');
const observed = { created: 0, live: 0, peak: 0, terminations: 0, limits: [] };
const makeWorker = (url, options) => {
  const worker = new Worker(url, options);
  observed.created += 1;
  observed.live += 1;
  observed.peak = Math.max(observed.peak, observed.live);
  observed.limits.push({ oldGenerationMb: options?.resourceLimits?.maxOldGenerationSizeMb, stackMb: options?.resourceLimits?.stackSizeMb, execArgvPresent: Object.hasOwn(options, 'execArgv') });
  worker.once('exit', () => { observed.live -= 1; });
  const terminate = worker.terminate.bind(worker);
  worker.terminate = () => { observed.terminations += 1; return terminate(); };
  return worker;
};
const pool = submission.createSumPool({ size: 2, maxQueued: 2, timeoutMs: 2000, makeWorker });
try {
  const jobs = [[1, 2, 3], [-2, 5], [], [1000000, -1000000, 7]];
  const results = await Promise.all(jobs.map(values => pool.submit(values)));
  await pool.close();
  observe({ results, created: observed.created, peak: observed.peak, live: observed.live, limits: observed.limits, final: pool.stats() });
} finally { await pool.close(); }

